alter table public.certificates add column if not exists participant_name text, add column if not exists certificate_type text not null default 'Certificate of Completion', add column if not exists program_title text, add column if not exists completion_hours integer, add column if not exists criteria text, add column if not exists disclaimer text not null default 'Independent preparation-program recognition; not an official IELTS or TOEFL certificate or score.';
create index if not exists certificates_number on public.certificates(certificate_no);
create or replace function public.verify_recognition_certificate(code text) returns table(certificate_no text,participant_name text,certificate_type text,program_title text,completion_hours integer,issued_at timestamptz,is_valid boolean,disclaimer text) language sql security definer set search_path=public as $$ select c.certificate_no,c.participant_name,c.certificate_type,c.program_title,c.completion_hours,c.issued_at,(c.revoked_at is null),c.disclaimer from public.certificates c where lower(c.certificate_no)=lower(code) limit 1 $$;
grant execute on function public.verify_recognition_certificate(text) to anon,authenticated;
